START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261120165404_AgregarPuntuacionesPublicacionConCupo') THEN
    CREATE TABLE puntuaciones_publicacion (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "UsuarioId" integer NOT NULL,
        "PublicacionId" integer NOT NULL,
        "Puntaje" integer,
        "FechaActualizacion" timestamp with time zone NOT NULL,
        "PendienteDeProyectar" boolean NOT NULL,
        CONSTRAINT "PK_puntuaciones_publicacion" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_puntuaciones_publicacion_puntaje" CHECK ( "Puntaje" BETWEEN 1 AND 5 ),
        CONSTRAINT "FK_puntuaciones_publicacion_Publicaciones_PublicacionId" FOREIGN KEY ("PublicacionId") REFERENCES "Publicaciones" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_puntuaciones_publicacion_Usuario_UsuarioId" FOREIGN KEY ("UsuarioId") REFERENCES "Usuario" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

